#!/usr/bin/env python3
"""Lifts the OpenAI Responses request models out of api/LlmProvider.kt.

LlmProvider.kt is the provider abstraction: it pulls in the whole message-preparation and
cost-model cluster, none of which the Responses request models need. The four model declarations
below are copied verbatim (annotations included) into a standalone file so the stand can compile
the real models instead of hand-written copies.
"""
import sys

HEADER = """\
// GENERATED by extract_responses_models.py from api/LlmProvider.kt -- do not edit.
//
// The OpenAI Responses request models are copied verbatim; only the file they live in (the
// provider abstraction) is left behind, because that file pulls in the message-preparation and
// cost-model clusters.
package com.newoether.agora.api

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject

"""

CLASSES = [
    "OpenAiResponsesRequest",
    "OpenAiResponseInputItem",
    "OpenAiResponseInputContent",
    "OpenAiResponseTool",
]


def extract(lines, name):
    start = None
    for index, line in enumerate(lines):
        if line.startswith("@Serializable") and index + 1 < len(lines) and \
                lines[index + 1].startswith("data class %s(" % name):
            start = index
            break
    if start is None:
        raise SystemExit("error: %s not found" % name)
    end = None
    for index in range(start + 1, len(lines)):
        # A data class ends with ")", a class with a body with "}".
        if lines[index] in ("}", ")"):
            end = index
            break
    if end is None:
        raise SystemExit("error: end of %s not found" % name)
    return lines[start:end + 1]


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: extract_responses_models.py <LlmProvider.kt> <out.kt>", file=sys.stderr)
        return 2

    lines = open(sys.argv[1], encoding="utf-8").read().split("\n")
    blocks = []
    for name in CLASSES:
        blocks.append("\n".join(extract(lines, name)))
    text = HEADER + "\n\n".join(blocks) + "\n"
    for name in CLASSES:
        if name not in text:
            raise SystemExit("error: %s missing from the extracted region" % name)
    with open(sys.argv[2], "w", encoding="utf-8") as handle:
        handle.write(text)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
